translation.example:
import numpy as np
from BB import sane
def sys(x):
    return np.array([x[0] - 1.0, x[1] - 2.0])
def one():
    res = sane([0.0, 0.0], sys, control={"NM": False, "BFGS": False, "trace": False}, quiet=True)
    return np.array([res["par"][0], res["par"][1], res["residual"], res["fn.reduction"], res["feval"], res["iter"], res["convergence"]])
print(one())
